const findEventsByIDs = `-- name: FindEventsByIDs :many
select tenant_id, diagnostic_id, cursor, event_id, event_fingerprint, event_version, operation_id, producer_operation_ref, parent_producer_operation_ref, participant_id, source, name, phase, state, expectation_name, expectation_version, checkpoint_key, checkpoint_class, deadline_at, journey_id, trace_id, span_id, request_id, command_id, provider_id, retry_group_ref, attempt, release_id, source_commit, occurred_at, received_at, producer_sequence, safe_attributes
from diagnostic_events
where tenant_id = $1
  and diagnostic_id = $2
  and event_id = any($3::text[])
order by cursor asc
`

type FindEventsByIDsParams struct {
	TenantID     pgtype.UUID `json:"tenant_id"`
	DiagnosticID pgtype.UUID `json:"diagnostic_id"`
	EventIds     []string    `json:"event_ids"`
}

func (q *Queries) FindEventsByIDs(ctx context.Context, arg FindEventsByIDsParams) ([]DiagnosticEvent, error) {
	rows, err := q.db.Query(ctx, findEventsByIDs, arg.TenantID, arg.DiagnosticID, arg.EventIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DiagnosticEvent
	for rows.Next() {
		var i DiagnosticEvent
		if err := rows.Scan(
			&i.TenantID,
			&i.DiagnosticID,
			&i.Cursor,
			&i.EventID,
			&i.EventFingerprint,
			&i.EventVersion,
			&i.OperationID,
			&i.ProducerOperationRef,
			&i.ParentProducerOperationRef,
			&i.ParticipantID,
			&i.Source,
			&i.Name,
			&i.Phase,
			&i.State,
			&i.ExpectationName,
			&i.ExpectationVersion,
			&i.CheckpointKey,
			&i.CheckpointClass,
			&i.DeadlineAt,
			&i.JourneyID,
			&i.TraceID,
			&i.SpanID,
			&i.RequestID,
			&i.CommandID,
			&i.ProviderID,
			&i.RetryGroupRef,
			&i.Attempt,
			&i.ReleaseID,
			&i.SourceCommit,
			&i.OccurredAt,
			&i.ReceivedAt,
			&i.ProducerSequence,
			&i.SafeAttributes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

